BEGIN; CREATE TABLE t1(a, b); INSERT INTO t1(a, b) VALUES('alpha-seed', 0); INSERT INTO t1(a, b) VALUES('bravo-seed', 0); INSERT INTO t1(a, b) SELECT a || '-1', 0 FROM t1; INSERT INTO t1(a, b) SELECT a || '-2', 0 FROM t1; INSERT INTO t1(a, b) SELECT a || '-3', 0 FROM t1; INSERT INTO t1(a, b) SELECT a || '-4', 0 FROM t1; INSERT INTO t1(a, b) SELECT a || '-5', 0 FROM t1; COMMIT; SELECT count(*) FROM t1;